body.content:
/* THE JUNE SHOP — Mystery Box V4 shared styles */
:root {
  --tjs-paper:#F6F4EE; --tjs-paper-2:#F1EFE9; --tjs-ink:#111214; --tjs-muted:#69665F;
  --tjs-gold:#D8BE63; --tjs-yellow:#E7DC36; --tjs-white:#fff; --tjs-dark:#111214;
  --tjs-line:rgba(17,18,20,.14); --tjs-line-strong:rgba(17,18,20,.24);
  --tjs-serif: Georgia, 'Times New Roman', serif;
  --tjs-condensed: 'Arial Narrow','Roboto Condensed','Helvetica Neue Condensed',Arial,sans-serif;
  --tjs-sans: Arial,Helvetica,sans-serif;
  --tjs-page-max:1440px; --tjs-content-max:1280px; --tjs-gutter:clamp(16px,4vw,64px);
  --tjs-radius:14px; --tjs-radius-card:12px; --tjs-radius-button:10px;
  --tjs-fast:160ms; --tjs-ui:240ms; --tjs-story:480ms; --tjs-hero:650ms;
  --tjs-ease-premium:cubic-bezier(.22,.75,.18,1); --tjs-ease-ui:cubic-bezier(.4,0,.2,1);
}
.tjs-mv4,.tjs-mv4 *,.tjs-mv4 *::before,.tjs-mv4 *::after{box-sizing:border-box}
.tjs-mv4{background:var(--tjs-paper);color:var(--tjs-ink);font-family:var(--tjs-sans);position:relative;overflow:clip}
.tjs-mv4__shell{width:min(100%,var(--tjs-page-max));margin:auto;padding-left:var(--tjs-gutter);padding-right:var(--tjs-gutter)}
.tjs-mv4__content{width:min(100%,var(--tjs-content-max));margin:auto}
.tjs-mv4__eyebrow{font-family:var(--tjs-condensed);font-size:10px;line-height:1.2;letter-spacing:.16em;text-transform:uppercase;font-weight:700}
.tjs-mv4__display{font-family:var(--tjs-serif);font-weight:400;letter-spacing:-.035em;line-height:.94;margin:0}
.tjs-mv4__body{font-size:14px;line-height:1.55;color:var(--tjs-muted);margin:0}
.tjs-mv4 button,.tjs-mv4 summary{font:inherit}
.tjs-mv4 button:focus-visible,.tjs-mv4 a:focus-visible,.tjs-mv4 summary:focus-visible{outline:2px solid var(--tjs-gold);outline-offset:3px}
.tjs-mv4 [data-reveal]{opacity:0;transform:translateY(14px);transition:opacity var(--tjs-story) var(--tjs-ease-premium),transform var(--tjs-story) var(--tjs-ease-premium)}
.tjs-mv4 [data-reveal].is-visible{opacity:1;transform:none}

/* hero */
.tjs-mv4-hero{padding:10px 0 32px}
.tjs-mv4-hero__grid{display:grid;grid-template-columns:minmax(0,1.28fr) minmax(390px,1fr);gap:14px}
.tjs-mv4-hero__media,.tjs-mv4-hero__buy{border:1px solid var(--tjs-line);border-radius:var(--tjs-radius);overflow:hidden}
.tjs-mv4-hero__media{min-height:680px;position:relative;display:grid;place-items:center;background:radial-gradient(circle at 20% 8%,rgba(255,255,255,.96),transparent 31%),radial-gradient(circle at 80% 82%,rgba(216,190,99,.15),transparent 28%),linear-gradient(135deg,var(--tjs-paper-2),#fbfaf6)}
.tjs-mv4-hero__media::after{content:"";position:absolute;inset:0;background-image:linear-gradient(rgba(17,18,20,.035) 1px,transparent 1px),linear-gradient(90deg,rgba(17,18,20,.035) 1px,transparent 1px);background-size:24px 24px;pointer-events:none}
.tjs-mv4-hero__img{position:absolute;inset:0;width:100%;height:100%;object-fit:contain;padding:clamp(46px,6vw,90px);filter:drop-shadow(0 24px 26px rgba(0,0,0,.18));z-index:2}
.tjs-mv4-hero__fallback{width:min(70%,520px);aspect-ratio:1.3/.72;position:relative;z-index:2;filter:drop-shadow(0 22px 24px rgba(0,0,0,.2))}
.tjs-mv4-hero__fallback::before{content:"";position:absolute;inset:12% 0 0;background:linear-gradient(145deg,#121315,#242629 55%,#0d0e10);border-radius:8px}
.tjs-mv4-hero__fallback::after{content:"";position:absolute;left:36%;top:0;width:28%;height:100%;background:linear-gradient(90deg,#cdb55f,#e8d68d 48%,#cdb55f);box-shadow:0 6px 20px rgba(0,0,0,.18)}
.tjs-mv4-hero__drop{position:absolute;top:22px;left:22px;z-index:4;font-family:var(--tjs-condensed);font-size:9px;font-weight:700;letter-spacing:.15em;text-transform:uppercase}
.tjs-mv4-hero__tape{position:absolute;left:7%;bottom:13%;z-index:5;padding:12px 22px;background:var(--tjs-yellow);color:var(--tjs-ink);font-family:var(--tjs-condensed);font-weight:800;letter-spacing:.08em;text-transform:uppercase;font-size:clamp(12px,1.2vw,17px);transform:rotate(var(--tjs-tape-angle,-6deg)) scaleX(0);transform-origin:left center;box-shadow:0 9px 18px rgba(0,0,0,.16)}
.tjs-mv4-hero__tape.is-visible{animation:tjsTapeIn var(--tjs-hero) var(--tjs-ease-premium) forwards}
@keyframes tjsTapeIn{0%{opacity:0;transform:rotate(var(--tjs-tape-angle,-6deg)) scaleX(0)}12%{opacity:1}86%{transform:rotate(var(--tjs-tape-angle,-6deg)) scaleX(1.035)}100%{opacity:1;transform:rotate(var(--tjs-tape-angle,-6deg)) scaleX(1)}}
.tjs-mv4-hero__buy{padding:clamp(26px,3vw,44px);background:rgba(255,255,255,.42);display:flex;flex-direction:column;justify-content:center}
.tjs-mv4-hero__h1{font-size:clamp(50px,5vw,72px);margin:10px 0 16px;max-width:720px}
.tjs-mv4-highlight{position:relative;display:inline-block;z-index:0}
.tjs-mv4-highlight::before{content:"";position:absolute;left:-.05em;right:-.05em;bottom:.08em;height:.24em;background:var(--tjs-yellow);z-index:-1;transform:scaleX(0);transform-origin:left center;transition:transform 300ms var(--tjs-ease-premium) 220ms}
.is-visible .tjs-mv4-highlight::before,.tjs-mv4-highlight.is-visible::before{transform:scaleX(1)}
.tjs-mv4-hero__copy{font-size:15px;max-width:520px;margin-bottom:24px}
.tjs-mv4-tier-head{display:flex;align-items:center;justify-content:space-between;gap:16px;margin-bottom:9px}
.tjs-mv4-tier-head small{font-size:10px;color:var(--tjs-muted)}
.tjs-mv4-tiers{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:9px}
.tjs-mv4-tier{appearance:none;text-align:left;background:transparent;border:1px solid var(--tjs-line-strong);color:var(--tjs-ink);border-radius:var(--tjs-radius-card);min-height:150px;padding:16px;cursor:pointer;position:relative;overflow:hidden;transition:background var(--tjs-ui) var(--tjs-ease-ui),color var(--tjs-ui) var(--tjs-ease-ui),border-color var(--tjs-ui) var(--tjs-ease-ui),transform var(--tjs-fast) var(--tjs-ease-ui)}
.tjs-mv4-tier:hover{transform:translateY(-1px)}
.tjs-mv4-tier[aria-pressed="true"]{background:var(--tjs-ink);color:var(--tjs-paper);border-color:var(--tjs-ink)}
.tjs-mv4-tier__kicker{font-family:var(--tjs-condensed);font-size:9px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;opacity:.8}
.tjs-mv4-tier__price{font-family:var(--tjs-serif);font-size:34px;line-height:1;margin:20px 0 7px;letter-spacing:-.03em}
.tjs-mv4-tier__value{font-family:var(--tjs-condensed);font-size:12px;font-weight:800;letter-spacing:.04em}
.tjs-mv4-tier__save{font-size:10px;margin-top:7px;opacity:.72}
.tjs-mv4-tier__badge{position:absolute;right:10px;top:10px;padding:5px 7px;background:var(--tjs-yellow);color:var(--tjs-ink);border-radius:999px;font-family:var(--tjs-condensed);font-size:8px;font-weight:800;letter-spacing:.08em;text-transform:uppercase}
.tjs-mv4-tier__check{position:absolute;right:10px;top:10px;width:21px;height:21px;border-radius:50%;display:grid;place-items:center;background:var(--tjs-gold);color:var(--tjs-ink);font-size:11px;opacity:0;transform:scale(.7);transition:opacity var(--tjs-fast),transform var(--tjs-fast)}
.tjs-mv4-tier[aria-pressed="true"] .tjs-mv4-tier__check{opacity:1;transform:scale(1)}
.tjs-mv4-tier[disabled]{opacity:.42;cursor:not-allowed;transform:none}
.tjs-mv4-summary{margin-top:12px;display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--tjs-line);border-bottom:1px solid var(--tjs-line)}
.tjs-mv4-summary__item{padding:14px 10px;text-align:center;min-width:0}
.tjs-mv4-summary__item+.tjs-mv4-summary__item{border-left:1px solid var(--tjs-line)}
.tjs-mv4-summary__label{font-family:var(--tjs-condensed);font-size:8px;letter-spacing:.14em;text-transform:uppercase;font-weight:700;color:var(--tjs-muted)}
.tjs-mv4-summary__value{font-family:var(--tjs-serif);font-size:21px;line-height:1.1;margin-top:5px;white-space:nowrap}
.tjs-mv4-value-swap{display:inline-block;transition:opacity 110ms ease,transform 110ms ease}
.tjs-mv4-value-swap.is-changing{opacity:0;transform:translateY(-5px)}
.tjs-mv4-cta{margin-top:13px;width:100%;height:58px;border:0;border-radius:var(--tjs-radius-button);background:var(--tjs-ink);color:#fff;display:grid;grid-template-columns:1fr 48px;align-items:center;padding:0;cursor:pointer;overflow:hidden;font-family:var(--tjs-condensed);font-size:12px;font-weight:800;letter-spacing:.08em;text-transform:uppercase;box-shadow:0 12px 24px rgba(0,0,0,.09);transition:box-shadow var(--tjs-fast),transform var(--tjs-fast)}
.tjs-mv4-cta__arrow{height:100%;display:grid;place-items:center;background:var(--tjs-gold);color:var(--tjs-ink);transition:transform var(--tjs-fast),width var(--tjs-fast)}
.tjs-mv4-cta:hover{box-shadow:0 16px 30px rgba(0,0,0,.14)}.tjs-mv4-cta:hover .tjs-mv4-cta__arrow{transform:translateX(3px)}.tjs-mv4-cta:active{transform:translateY(1px) scale(.995)}
.tjs-mv4-cta[disabled]{opacity:.5;cursor:not-allowed}
.tjs-mv4-trust{display:grid;grid-template-columns:repeat(4,1fr);gap:0;margin-top:16px;border-top:1px solid var(--tjs-line)}
.tjs-mv4-trust__item{padding:13px 10px 0}.tjs-mv4-trust__item+.tjs-mv4-trust__item{border-left:1px solid var(--tjs-line)}
.tjs-mv4-trust__title{font-family:var(--tjs-condensed);font-size:9px;letter-spacing:.08em;font-weight:800;text-transform:uppercase}.tjs-mv4-trust__copy{font-size:10px;line-height:1.4;color:var(--tjs-muted);margin-top:4px}
.tjs-mv4-editor-note{margin-top:10px;padding:10px 12px;border:1px solid #d7be62;background:#fff8d8;font-size:11px;line-height:1.45;color:#554719;border-radius:8px}

/* guarantees */
.tjs-mv4-guarantees{padding:clamp(64px,8vw,110px) 0}
.tjs-mv4-guarantees__grid{display:grid;grid-template-columns:.75fr 1.35fr;gap:clamp(40px,7vw,110px);align-items:start}
.tjs-mv4-guarantees__heading{font-size:clamp(42px,4.7vw,66px);margin:10px 0 18px}
.tjs-mv4-guarantees__items{display:grid;grid-template-columns:repeat(2,1fr);gap:0 24px}
.tjs-mv4-guarantee{position:relative;padding:26px 0 28px;border-top:1px solid var(--tjs-line);min-height:150px}
.tjs-mv4-guarantee__num{font-family:var(--tjs-condensed);font-size:58px;font-weight:800;line-height:.75;opacity:.07;position:absolute;top:22px;right:0}
.tjs-mv4-guarantee h3{font-family:var(--tjs-serif);font-size:25px;font-weight:400;line-height:1.08;margin:0 0 10px}.tjs-mv4-guarantee p{font-size:12px;line-height:1.55;color:var(--tjs-muted);margin:0;max-width:420px}

/* dark value */
.tjs-mv4-value{padding:16px 0 24px}.tjs-mv4-value__panel{min-height:640px;background:radial-gradient(circle at 72% 30%,rgba(216,190,99,.10),transparent 32%),var(--tjs-dark);color:#fff;position:relative;overflow:hidden;padding:clamp(44px,6vw,86px);display:flex;flex-direction:column;justify-content:space-between}
.tjs-mv4-value__headline{font-family:var(--tjs-condensed);font-size:clamp(72px,9vw,138px);font-weight:800;line-height:.82;letter-spacing:-.045em;text-transform:uppercase;margin:0;max-width:980px;position:relative;z-index:2}
.tjs-mv4-value__tape{position:absolute;left:34%;top:43%;background:var(--tjs-yellow);color:var(--tjs-ink);padding:14px 28px;font-family:var(--tjs-condensed);font-size:clamp(16px,2vw,28px);font-weight:800;letter-spacing:.04em;text-transform:uppercase;transform:translateX(-120%) rotate(var(--tjs-value-tape-angle,-7deg));box-shadow:0 16px 30px rgba(0,0,0,.24);z-index:3;white-space:nowrap}.tjs-mv4-value__tape.is-visible{animation:tjsValueTape 520ms var(--tjs-ease-premium) 180ms forwards}@keyframes tjsValueTape{to{transform:translateX(0) rotate(var(--tjs-value-tape-angle,-7deg))}}
.tjs-mv4-value__data{display:grid;grid-template-columns:repeat(2,minmax(0,320px));gap:34px;position:relative;z-index:2}.tjs-mv4-value__datum{border-top:1px solid rgba(255,255,255,.23);padding-top:14px}.tjs-mv4-value__datum label{font-family:var(--tjs-condensed);font-size:9px;letter-spacing:.14em;text-transform:uppercase;color:rgba(255,255,255,.58);font-weight:700}.tjs-mv4-value__datum strong{display:block;font-family:var(--tjs-serif);font-size:clamp(48px,5vw,72px);font-weight:400;letter-spacing:-.04em;margin-top:6px}.tjs-mv4-value__footer{position:absolute;left:clamp(44px,6vw,86px);right:clamp(44px,6vw,86px);bottom:24px;border-top:1px solid rgba(255,255,255,.16);padding-top:13px;font-size:11px;color:rgba(255,255,255,.6)}

/* shake */
.tjs-mv4-shake{padding:clamp(64px,8vw,110px) 0;text-align:center}.tjs-mv4-shake__heading{font-size:clamp(42px,5vw,68px);margin:9px 0 20px}.tjs-mv4-shake__stage{width:min(100%,650px);margin:24px auto 0;min-height:360px;display:grid;place-items:center;position:relative}.tjs-mv4-shake__img{width:min(74%,380px);max-height:320px;object-fit:contain;filter:drop-shadow(0 24px 25px rgba(0,0,0,.18));cursor:pointer}.tjs-mv4-shake__fallback{width:340px;max-width:72%;aspect-ratio:1.3/.72;position:relative;cursor:pointer;filter:drop-shadow(0 20px 22px rgba(0,0,0,.2))}.tjs-mv4-shake__fallback::before{content:"";position:absolute;inset:12% 0 0;background:#151619;border-radius:8px}.tjs-mv4-shake__fallback::after{content:"";position:absolute;left:40%;top:0;width:20%;height:100%;background:var(--tjs-gold)}.is-shaking{animation:tjsShake 420ms ease-in-out}@keyframes tjsShake{0%,100%{transform:translateX(0) rotate(0)}20%{transform:translateX(-6px) rotate(-2deg)}40%{transform:translateX(6px) rotate(2deg)}60%{transform:translateX(-4px) rotate(-1deg)}80%{transform:translateX(3px) rotate(1deg)}}.tjs-mv4-shake__response{font-family:var(--tjs-serif);font-size:28px;margin-top:-20px}.tjs-mv4-shake__hint{font-size:11px;color:var(--tjs-muted);margin-top:5px}

/* journey */
.tjs-mv4-journey{padding:clamp(64px,8vw,105px) 0}.tjs-mv4-journey__heading{font-size:clamp(44px,5.2vw,72px);margin:9px 0 40px;max-width:720px}.tjs-mv4-journey__grid{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.tjs-mv4-step{border-top:1px solid var(--tjs-line);padding-top:20px;min-height:170px}.tjs-mv4-step__num{font-family:var(--tjs-condensed);font-size:16px;color:var(--tjs-muted);margin-bottom:28px}.tjs-mv4-step h3{font-family:var(--tjs-condensed);font-size:19px;letter-spacing:.02em;text-transform:uppercase;margin:0 0 9px}.tjs-mv4-step p{font-size:12px;color:var(--tjs-muted);line-height:1.55;margin:0;max-width:330px}

/* gift */
.tjs-mv4-gift{padding:clamp(50px,7vw,96px) 0}.tjs-mv4-gift__grid{display:grid;grid-template-columns:1fr 1fr;min-height:560px;border-top:1px solid var(--tjs-line);border-bottom:1px solid var(--tjs-line)}.tjs-mv4-gift__media{background:var(--tjs-paper-2);display:grid;place-items:center;overflow:hidden;position:relative}.tjs-mv4-gift__media img{width:100%;height:100%;object-fit:cover}.tjs-mv4-gift__copy{padding:clamp(42px,6vw,86px);display:flex;flex-direction:column;justify-content:center}.tjs-mv4-gift__heading{font-size:clamp(46px,5vw,72px);margin:10px 0 18px}.tjs-mv4-gift__copy .tjs-mv4-cta{max-width:360px;margin-top:26px}

/* faq */
.tjs-mv4-faq{padding:clamp(64px,8vw,100px) 0}.tjs-mv4-faq__heading{font-size:clamp(48px,5vw,72px);margin:9px 0 30px}.tjs-mv4-faq details{border-top:1px solid var(--tjs-line);transition:background var(--tjs-fast),border-color var(--tjs-fast)}.tjs-mv4-faq details:last-child{border-bottom:1px solid var(--tjs-line)}.tjs-mv4-faq summary{list-style:none;display:flex;justify-content:space-between;gap:20px;padding:20px 4px;cursor:pointer;font-size:14px;font-weight:700}.tjs-mv4-faq summary::-webkit-details-marker{display:none}.tjs-mv4-faq__plus{transition:transform 180ms var(--tjs-ease-ui);font-size:18px}.tjs-mv4-faq details[open]{background:rgba(216,190,99,.055);border-left:2px solid var(--tjs-gold);padding-left:12px}.tjs-mv4-faq details[open] .tjs-mv4-faq__plus{transform:rotate(45deg)}.tjs-mv4-faq__answer{padding:0 36px 20px 4px;font-size:13px;line-height:1.6;color:var(--tjs-muted);max-width:850px}

/* final cta */
.tjs-mv4-final{padding:70px 0 100px;text-align:center}.tjs-mv4-final__heading{font-size:clamp(52px,6vw,88px);margin:8px auto 20px}.tjs-mv4-final__meta{display:flex;justify-content:center;gap:20px;margin:0 auto 22px;font-family:var(--tjs-condensed);font-size:12px;letter-spacing:.08em;text-transform:uppercase}.tjs-mv4-final .tjs-mv4-cta{max-width:440px;margin:0 auto}

/* sticky */
.tjs-mv4-sticky{display:none}

@media(max-width:1023px){
  .tjs-mv4-hero__grid{grid-template-columns:1fr}.tjs-mv4-hero__media{min-height:420px}.tjs-mv4-guarantees__grid{grid-template-columns:1fr;gap:36px}.tjs-mv4-gift__grid{grid-template-columns:1fr}.tjs-mv4-gift__media{min-height:420px}
}
@media(max-width:749px){
  :root{--tjs-gutter:16px}
  .tjs-mv4__eyebrow{font-size:9px}.tjs-mv4__body{font-size:14px}
  .tjs-mv4-hero{padding-top:6px}.tjs-mv4-hero__grid{gap:8px}.tjs-mv4-hero__media{min-height:0;height:var(--tjs-mobile-media-h,236px);border-radius:14px}.tjs-mv4-hero__img{padding:20px 42px 8px}.tjs-mv4-hero__drop{top:13px;left:13px;font-size:8px}.tjs-mv4-hero__tape{left:5%;bottom:12%;padding:8px 12px;font-size:10px}.tjs-mv4-hero__buy{border-radius:14px;padding:20px 14px 18px}.tjs-mv4-hero__h1{font-size:var(--tjs-mobile-h1,40px);line-height:.95;margin:8px 0 12px}.tjs-mv4-hero__copy{font-size:13px;line-height:1.48;margin-bottom:18px}.tjs-mv4-tier-head{margin-bottom:7px}.tjs-mv4-tier-head small{font-size:9px}.tjs-mv4-tiers{gap:7px}.tjs-mv4-tier{min-height:136px;padding:12px 10px;border-radius:10px}.tjs-mv4-tier__kicker{font-size:7px}.tjs-mv4-tier__price{font-size:28px;margin:18px 0 6px}.tjs-mv4-tier__value{font-size:9px}.tjs-mv4-tier__save{font-size:8px}.tjs-mv4-tier__badge{right:7px;top:7px;font-size:6px;padding:4px 5px}.tjs-mv4-tier__check{right:7px;top:7px;width:18px;height:18px;font-size:9px}.tjs-mv4-summary{margin-top:10px}.tjs-mv4-summary__item{padding:11px 4px}.tjs-mv4-summary__label{font-size:7px}.tjs-mv4-summary__value{font-size:17px}.tjs-mv4-cta{height:56px;margin-top:11px}.tjs-mv4-trust{grid-template-columns:repeat(2,1fr);margin-top:13px}.tjs-mv4-trust__item{padding:11px 8px}.tjs-mv4-trust__item:nth-child(3){border-left:0;border-top:1px solid var(--tjs-line)}.tjs-mv4-trust__item:nth-child(4){border-top:1px solid var(--tjs-line)}
  .tjs-mv4-guarantees{padding:64px 0}.tjs-mv4-guarantees__heading{font-size:38px;line-height:.95}.tjs-mv4-guarantees__items{grid-template-columns:1fr}.tjs-mv4-guarantee{min-height:0;padding:22px 0}.tjs-mv4-guarantee__num{font-size:46px}.tjs-mv4-guarantee h3{font-size:22px}.tjs-mv4-guarantee p{font-size:12px}
  .tjs-mv4-value{padding:8px 0 14px}.tjs-mv4-value__panel{min-height:540px;padding:38px 20px 66px}.tjs-mv4-value__headline{font-size:clamp(48px,15vw,62px)}.tjs-mv4-value__tape{left:8%;top:48%;font-size:14px;padding:10px 16px}.tjs-mv4-value__data{grid-template-columns:1fr 1fr;gap:18px}.tjs-mv4-value__datum strong{font-size:42px}.tjs-mv4-value__footer{left:20px;right:20px}
  .tjs-mv4-shake{padding:64px 0}.tjs-mv4-shake__heading{font-size:39px}.tjs-mv4-shake__stage{min-height:300px}.tjs-mv4-shake__img{width:min(78%,240px)}.tjs-mv4-shake__fallback{width:230px}.tjs-mv4-shake__response{font-size:24px}
  .tjs-mv4-journey{padding:64px 0}.tjs-mv4-journey__heading{font-size:40px}.tjs-mv4-journey__grid{grid-template-columns:1fr;gap:22px}.tjs-mv4-step{min-height:0;padding-top:16px}.tjs-mv4-step__num{margin-bottom:15px}
