/* ===== V4.3 MOTION + VISUAL POLISH OVERRIDES ===== */
html[data-tjs-mystery-motion="off"] .tjs-mv4 *,
html[data-tjs-mystery-motion="off"] .tjs-mv4 *::before,
html[data-tjs-mystery-motion="off"] .tjs-mv4 *::after{animation:none!important;transition:none!important}

/* stronger hero composition */
.tjs-mv4-hero__media{perspective:1100px;isolation:isolate}
.tjs-mv4-hero__product{position:relative;z-index:3;width:calc(var(--tjs-hero-product-scale, .78) * 100%);height:74%;display:grid;place-items:center;transform-style:preserve-3d;will-change:transform;transition:transform 600ms var(--tjs-ease-premium);filter:drop-shadow(0 28px 32px rgba(0,0,0,.18))}
.tjs-mv4-hero__product picture{display:block;width:100%;height:100%}
.tjs-mv4-hero__product .tjs-mv4-hero__img{position:relative;inset:auto;width:100%;height:100%;padding:0;object-fit:contain;filter:none;z-index:2}
.tjs-mv4-hero__product .tjs-mv4-hero__fallback{width:100%;max-width:620px;filter:none}
.tjs-mv4-hero__glow{position:absolute;left:16%;right:16%;bottom:3%;height:18%;border-radius:50%;background:radial-gradient(ellipse,rgba(216,190,99,.34),rgba(216,190,99,.08) 45%,transparent 72%);filter:blur(18px);transform:translateZ(-10px);pointer-events:none;opacity:.8}
.tjs-mv4-hero__impact{position:absolute;z-index:4;left:var(--tjs-tape-x,12%);top:var(--tjs-tape-y,64%);width:180px;height:54px;border-radius:50%;background:radial-gradient(ellipse,rgba(0,0,0,.20),transparent 70%);filter:blur(10px);opacity:0;pointer-events:none;transform:rotate(var(--tjs-tape-angle,-6deg)) scale(.7)}
.tjs-mv4-hero__tape{left:var(--tjs-tape-x,12%);bottom:auto;top:var(--tjs-tape-y,64%);transform:translateX(-150%) rotate(calc(var(--tjs-tape-angle,-6deg) - 4deg));clip-path:polygon(0 7%,98% 0,100% 88%,3% 100%)}
.tjs-mv4-hero__tape.is-visible{animation:tjsTapeSlap var(--tjs-hero) var(--tjs-ease-premium) forwards}
.tjs-mv4-hero__tape.is-visible + .tjs-mv4-hero__impact{animation:tjsTapeImpact 520ms ease 280ms forwards}
@keyframes tjsTapeSlap{0%{opacity:0;transform:translateX(-150%) rotate(calc(var(--tjs-tape-angle,-6deg) - 4deg)) scaleX(.88)}12%{opacity:1}72%{transform:translateX(3%) rotate(calc(var(--tjs-tape-angle,-6deg) + 1deg)) scaleX(1.045)}88%{transform:translateX(-1%) rotate(var(--tjs-tape-angle,-6deg)) scaleX(.995)}100%{opacity:1;transform:translateX(0) rotate(var(--tjs-tape-angle,-6deg)) scaleX(1)}}
@keyframes tjsTapeImpact{0%{opacity:0;transform:rotate(var(--tjs-tape-angle,-6deg)) scale(.65)}35%{opacity:.36;transform:rotate(var(--tjs-tape-angle,-6deg)) scale(1.18)}100%{opacity:0;transform:rotate(var(--tjs-tape-angle,-6deg)) scale(1.45)}}

/* marker stroke */
.tjs-mv4-highlight{position:relative;display:inline-block;z-index:0;background:none!important}
.tjs-mv4-highlight::before{content:"";position:absolute;z-index:-1;left:-.06em;right:-.08em;bottom:.10em;height:.25em;background:var(--tjs-yellow);transform:scaleX(0) skewX(-5deg);transform-origin:left center;clip-path:polygon(1% 22%,99% 0,100% 82%,0 100%)}
.tjs-mv4-highlight.is-highlighted::before{animation:tjsMarkerSwipe 420ms var(--tjs-ease-premium) forwards}
@keyframes tjsMarkerSwipe{0%{transform:scaleX(0) skewX(-5deg)}88%{transform:scaleX(1.04) skewX(-5deg)}100%{transform:scaleX(1) skewX(-5deg)}}

/* commerce breathing room */
