.tjs-mv4-tier{isolation:isolate;background:transparent!important}
.tjs-mv4-tier::before{content:"";position:absolute;z-index:0;left:0;right:0;bottom:0;height:100%;background:var(--tjs-ink);transform:scaleY(0);transform-origin:bottom center;transition:transform 270ms var(--tjs-ease-premium)}
