.is-shaking{animation:tjsShakePro 440ms ease-in-out!important}
@keyframes tjsShakePro{0%,100%{transform:translateX(0) rotate(0)}16%{transform:translateX(calc(var(--tjs-shake-strength,7px) * -1)) rotate(-2.6deg)}34%{transform:translateX(var(--tjs-shake-strength,7px)) rotate(2.4deg)}52%{transform:translateX(calc(var(--tjs-shake-strength,7px) * -.72)) rotate(-1.5deg)}70%{transform:translateX(calc(var(--tjs-shake-strength,7px) * .55)) rotate(1deg)}86%{transform:translateX(calc(var(--tjs-shake-strength,7px) * -.25)) rotate(-.4deg)}}
.tjs-mv4-shake__response{margin-top:-8px}

