.tjs-mv4-guarantees{padding-top:var(--tjs-guarantees-pt,76px);padding-bottom:var(--tjs-guarantees-pb,76px)}
.tjs-mv4-guarantee{min-height:128px;padding:22px 0 24px}
.tjs-mv4-guarantee__num{right:10px;top:18px;font-size:52px;opacity:.055;pointer-events:none}

.tjs-mv4-value{padding:10px 0 18px}
.tjs-mv4-value__panel{min-height:590px}
.tjs-mv4-value__tape{top:52%}
.tjs-mv4-value__data{margin-top:14px}
.tjs-mv4-value__datum strong{font-size:clamp(54px,5.4vw,78px)}

.tjs-mv4-shake{padding-top:var(--tjs-shake-pt,70px);padding-bottom:var(--tjs-shake-pb,70px)}
.tjs-mv4-shake__stage{min-height:360px}
.tjs-mv4-shake__img,.tjs-mv4-shake__fallback{width:min(88%,var(--tjs-shake-box-size,460px))}

.tjs-mv4-journey{padding-top:var(--tjs-journey-pt,70px);padding-bottom:var(--tjs-journey-pb,54px)}
.tjs-mv4-journey__heading{margin-bottom:28px}
.tjs-mv4-step{min-height:145px}
.tjs-mv4-step__num{font-size:18px;margin-bottom:20px}
.tjs-mv4-step h3{font-size:21px}
.tjs-mv4-step p{font-size:13px}

.tjs-mv4-gift{padding-top:var(--tjs-gift-pt,54px);padding-bottom:var(--tjs-gift-pb,54px)}
.tjs-mv4-gift__grid{min-height:500px}
.tjs-mv4-gift__box{width:72%}
.tjs-mv4-gift__copy{padding:clamp(38px,5vw,72px)}

.tjs-mv4-faq{padding-top:var(--tjs-faq-pt,54px);padding-bottom:var(--tjs-faq-pb,72px)}
.tjs-mv4-faq__heading{margin-bottom:24px}

/* campaign template header-overlap protection */
.tjs-mystery-v4-hero-section,.tjs-mystery-v4-guarantees-section,.tjs-mystery-v4-value-section,.tjs-mystery-v4-shake-section,.tjs-mystery-v4-journey-section,.tjs-mystery-v4-gift-section,.tjs-mystery-v4-faq-section{scroll-margin-top:var(--tjs-sticky-offset,104px)}

@media(max-width:1023px){
  .tjs-mv4-hero__media{min-height:420px}
  .tjs-mv4-hero__product{transform:translateY(-2%) scale(min(var(--tjs-hero-product-scale,.88),.94))}
  .tjs-mv4-gift__grid{min-height:0}
}
@media(max-width:749px){
  .tjs-mv4{scroll-margin-top:84px}
  .tjs-mv4-hero__product{transform:translateY(-1%) scale(.96)}
  .tjs-mv4-hero__tape{top:auto;bottom:11%;left:5%}
  .tjs-mv4-tier{padding:14px 11px 12px}
  .tjs-mv4-tier__check{right:8px!important;top:8px!important}
  .tjs-mv4-tier__badge{left:8px!important;top:8px!important}
  .tjs-mv4-tier:has(.tjs-mv4-tier__badge) .tjs-mv4-tier__kicker{padding-top:25px;padding-right:24px}
  .tjs-mv4-summary__value{font-size:20px}
  .tjs-mv4-trust{grid-template-columns:repeat(2,1fr)}
  .tjs-mv4-guarantees{padding:54px 0}
  .tjs-mv4-value__panel{min-height:520px}
  .tjs-mv4-shake{padding:54px 0}.tjs-mv4-shake__stage{min-height:300px}
  .tjs-mv4-journey{padding:54px 0 42px}.tjs-mv4-journey__heading{margin-bottom:24px}.tjs-mv4-step{min-height:0}
  .tjs-mv4-gift{padding:42px 0}.tjs-mv4-gift__box{width:78%}
  .tjs-mv4-faq{padding:46px 0 58px}
}

/* V4.9 — mobile rhythm pass; cart + variant JS intentionally untouched */
@media(max-width:749px){
  /* Hero: get to the buying decision faster */
  .tjs-mv4-hero{padding:4px 0 var(--tjs-mobile-hero-pb,18px)}
  .tjs-mv4-hero__grid{gap:var(--tjs-mobile-hero-gap,6px)}
  .tjs-mv4-hero__media{height:var(--tjs-mobile-media-h,220px);min-height:0}
  .tjs-mv4-hero__product{width:82%;height:88%;transform:translateY(-2%) scale(.98)}
  .tjs-mv4-hero__buy{padding:var(--tjs-mobile-buy-pad,14px)}
  .tjs-mv4-hero__h1{font-size:var(--tjs-mobile-h1,38px);margin:6px 0 9px;line-height:.93}
  .tjs-mv4-hero__copy{margin-bottom:13px;line-height:1.42}
  .tjs-mv4-tier-head{margin-bottom:6px}
  .tjs-mv4-tiers{gap:6px}
  .tjs-mv4-tier{min-height:126px;padding:13px 10px 11px}
  .tjs-mv4-tier__price{font-size:27px;margin:16px 0 5px}
  .tjs-mv4-summary{margin-top:8px}
  .tjs-mv4-summary__item{padding:9px 3px}
  .tjs-mv4-summary__value{font-size:18px;margin-top:4px}
  .tjs-mv4-cta{height:52px;margin-top:9px}
  .tjs-mv4-trust{margin-top:10px}
  .tjs-mv4-trust__item{padding:9px 8px 8px}
  .tjs-mv4-trust__title{font-size:8px}
  .tjs-mv4-trust__copy{font-size:9px;line-height:1.35}

  /* Journey: compact story rhythm; no dead zone before Gift */
  .tjs-mv4-journey{padding-top:var(--tjs-journey-mpt,40px);padding-bottom:var(--tjs-journey-mpb,32px)}
  .tjs-mv4-journey__heading{font-size:37px;line-height:.96;margin:7px 0 18px}
  .tjs-mv4-journey__grid{gap:var(--tjs-journey-mgap,14px)}
  .tjs-mv4-step{padding-top:13px}
  .tjs-mv4-step__num{font-size:15px;margin-bottom:8px}
  .tjs-mv4-step h3{font-size:17px;margin-bottom:5px}
  .tjs-mv4-step p{font-size:12px;line-height:1.45}
  .tjs-mv4-journey__track{top:112px;bottom:38px}

  /* Gift: keep image + copy feeling like one editorial unit */
  .tjs-mv4-gift{padding-top:var(--tjs-gift-mpt,30px);padding-bottom:var(--tjs-gift-mpb,34px)}
  .tjs-mv4-gift__grid{min-height:0}
  .tjs-mv4-gift__media{min-height:var(--tjs-gift-media-h,260px)}
  .tjs-mv4-gift__box{width:82%}
  .tjs-mv4-gift__copy{padding:var(--tjs-gift-copy-pad,18px)}
  .tjs-mv4-gift__heading{font-size:37px;line-height:.96;margin:7px 0 12px}
  .tjs-mv4-gift__copy .tjs-mv4-cta{margin-top:18px;height:52px}

  /* FAQ: pull it upward and reduce repetitive row height */
  .tjs-mv4-faq{padding-top:var(--tjs-faq-mpt,34px);padding-bottom:var(--tjs-faq-mpb,46px)}
  .tjs-mv4-faq__heading{font-size:38px;line-height:.98;margin:7px 0 17px}
  .tjs-mv4-faq summary{padding:var(--tjs-faq-row-pad,14px) 3px;font-size:12.5px;line-height:1.35;align-items:center}
  .tjs-mv4-faq__plus{font-size:16px;flex:0 0 auto}
  .tjs-mv4-faq__answer{padding:0 28px 14px 3px;font-size:12px;line-height:1.5}
  .tjs-mv4-faq details[open] summary{padding-bottom:10px}
}

@media(max-width:389px){
  .tjs-mv4-hero__media{height:min(var(--tjs-mobile-media-h,220px),210px)}
  .tjs-mv4-hero__h1{font-size:min(var(--tjs-mobile-h1,38px),36px)}
  .tjs-mv4-tier{min-height:120px;padding-left:9px;padding-right:9px}
  .tjs-mv4-summary__value{font-size:16px}
  .tjs-mv4-journey__heading,.tjs-mv4-gift__heading,.tjs-mv4-faq__heading{font-size:35px}
}

/* =========================================================
   V5 — GRAPHIC EDITORIAL / SWISS CAMPAIGN SKIN
   Commerce selectors + AJAX logic remain unchanged.
   ========================================================= */

:root{
  --tjs-gutter:clamp(14px,3.2vw,46px);
  --tjs-line:rgba(17,17,17,.18);
  --tjs-line-strong:rgba(17,17,17,.36);
}

.tjs-mv4{
  font-family:var(--tjs-text);
  background:var(--tjs-paper);
  color:var(--tjs-ink);
}
.tjs-mv4::before{
  content:"";
  position:absolute;inset:0;pointer-events:none;z-index:0;
  opacity:var(--tjs-texture-alpha,.04);
  background-image:
    radial-gradient(circle at 20% 30%,#111 0 .45px,transparent .6px),
    radial-gradient(circle at 80% 70%,#111 0 .4px,transparent .55px);
  background-size:13px 13px,17px 17px;
  mix-blend-mode:multiply;
}
.tjs-mv4__shell,.tjs-mv4__content{position:relative;z-index:1}
.tjs-mv4__eyebrow{
  font-family:var(--tjs-micro);
  font-size:10px;line-height:1;
  letter-spacing:.08em;
  font-weight:700;
  text-transform:uppercase;
}
.tjs-mv4__display{
  font-family:var(--tjs-display);
  font-weight:var(--tjs-display-weight,700);
  letter-spacing:-.055em;
  line-height:.9;
}
.tjs-mv4__body{
  font-family:var(--tjs-text);
  font-size:14px;line-height:1.46;
  color:var(--tjs-muted)
}
.tjs-mv4 button,.tjs-mv4 summary{font-family:var(--tjs-text)}
.tjs-mv4 button:focus-visible,.tjs-mv4 summary:focus-visible{outline:2px solid var(--tjs-yellow);outline-offset:3px}

/* HERO: one integrated graphic canvas */
.tjs-mv4-hero{padding:10px 0 28px}
.tjs-mv4-hero__grid{
  display:grid;
  grid-template-columns:minmax(0,1.08fr) minmax(430px,.92fr);
  gap:0;
  border:1px solid var(--tjs-line-strong);
  border-radius:var(--tjs-radius);
  overflow:hidden;
  background:var(--tjs-paper);
  position:relative;
}
.tjs-mv4-hero__grid::before{
  content:"TJS / MYSTERY DROP / 001";
  position:absolute;z-index:8;left:18px;bottom:14px;
  font:700 9px/1 var(--tjs-micro);letter-spacing:.08em;
  pointer-events:none;
}
.tjs-mv4-hero__grid::after{
  content:"↘";
  position:absolute;z-index:8;right:18px;top:16px;
  font:700 25px/1 var(--tjs-display);
  pointer-events:none;
}
.tjs-mv4-hero__media,.tjs-mv4-hero__buy{
  border:0!important;border-radius:0!important;
  background:transparent;
}
.tjs-mv4-hero__media{
  min-height:var(--tjs-hero-desktop-height,620px);
  border-right:1px solid var(--tjs-line)!important;
  background:
    linear-gradient(rgba(17,17,17,var(--tjs-grid-alpha,.07)) 1px,transparent 1px),
    linear-gradient(90deg,rgba(17,17,17,var(--tjs-grid-alpha,.07)) 1px,transparent 1px),
    radial-gradient(circle at 68% 76%,color-mix(in srgb,var(--tjs-yellow) 14%,transparent),transparent 24%),
    var(--tjs-paper);
  background-size:var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),auto,auto;
  position:relative;
}
.tjs-mv4-hero__media::after{display:none}
.tjs-mv4-hero__drop{
  top:16px;left:16px;
  padding:0;
  font:700 9px/1 var(--tjs-micro);letter-spacing:.08em;
  background:transparent;
}
.tjs-mv4-hero__product{
  width:92%;height:88%;
  transform:translateY(var(--tjs-hero-product-y,-5%)) scale(var(--tjs-hero-product-scale,.92));
  transform-origin:center;
}
.tjs-mv4-hero__img{padding:32px;filter:drop-shadow(0 34px 30px rgba(0,0,0,.19))}
.tjs-mv4-hero__fallback{width:min(82%,650px);filter:drop-shadow(0 30px 28px rgba(0,0,0,.2))}
.tjs-mv4-hero__fallback::before{border-radius:2px;background:#141517}
.tjs-mv4-hero__fallback::after{background:linear-gradient(90deg,#e0cf78,#f1e6aa 46%,#ceb858)}
.tjs-mv4-hero__glow{opacity:.5}
.tjs-mv4-hero__tape{
  left:var(--tjs-tape-x,10%);top:var(--tjs-tape-y,62%);bottom:auto;
  padding:11px 18px;
  border-radius:1px;
  background:var(--tjs-yellow);
  color:var(--tjs-ink);
  font:800 clamp(12px,1.15vw,16px)/1 var(--tjs-micro);
  letter-spacing:.015em;
  box-shadow:7px 9px 0 rgba(17,17,17,.13);
}
.tjs-mv4-hero__impact{border-radius:0}

.tjs-mv4-hero__buy{
  padding:clamp(28px,3.4vw,52px);
  justify-content:center;
  position:relative;
  background:
    linear-gradient(180deg,rgba(255,255,255,.2),transparent 25%),
    var(--tjs-paper);
}
.tjs-mv4-hero__buy::before{
  content:"VALUE / KNOWN\A CONTENTS / CLASSIFIED";
  white-space:pre;
  position:absolute;right:18px;bottom:17px;
  font:700 8px/1.45 var(--tjs-micro);letter-spacing:.06em;text-align:right;
  opacity:.45;
}
.tjs-mv4-hero__h1{
  font-family:var(--tjs-display);
  font-weight:var(--tjs-display-weight,700);
  font-size:clamp(56px,5.6vw,var(--tjs-desktop-h1,82px));
  line-height:.82;
  letter-spacing:-.06em;
  text-transform:uppercase;
  margin:14px 0 18px;
  max-width:700px;
}
.tjs-mv5-hline{display:block;position:relative;width:max-content;max-width:100%}
.tjs-mv5-hline:nth-child(3){margin-top:.04em}
.tjs-mv4-highlight{display:inline-block;position:relative;z-index:1}
.tjs-mv4-highlight::before{
  left:-.04em;right:-.05em;bottom:.04em;height:.22em;
  background:var(--tjs-yellow);border-radius:1px;
  transform:scaleX(0) skewX(-4deg);
}
.is-visible .tjs-mv4-highlight::before,.tjs-mv4-highlight.is-visible::before{transform:scaleX(1) skewX(-4deg)}
.tjs-mv4-hero__copy{max-width:500px;font-size:14px;margin-bottom:22px;color:#4f524e}

/* Tier selector: editorial data objects, not Shopify cards */
.tjs-mv4-tier-head{border-top:1px solid var(--tjs-line-strong);padding-top:11px;margin:0 0 8px}
.tjs-mv4-tier-head small{font:500 10px/1 var(--tjs-text);color:var(--tjs-muted)}
.tjs-mv4-tiers{gap:8px}
.tjs-mv4-tier{
  min-height:var(--tjs-tier-h,168px);
  border-radius:var(--tjs-radius-card);
  border:1px solid var(--tjs-line-strong);
  padding:18px 16px 15px;
  background:transparent;
  color:var(--tjs-ink);
  box-shadow:none!important;
  overflow:hidden;
}
.tjs-mv4-tier::before{
  content:"";position:absolute;inset:auto 0 0;height:7px;
  background:var(--tjs-yellow);
  transform:scaleX(0);transform-origin:left center;
  transition:transform 240ms var(--tjs-ease-premium);
}
.tjs-mv4-tier:hover{transform:none;border-color:var(--tjs-ink)}
.tjs-mv4-tier.is-selected,.tjs-mv4-tier[data-selected="true"],.tjs-mv4-tier[aria-pressed="true"]{
  background:var(--tjs-ink)!important;
  color:var(--tjs-paper)!important;
  border-color:var(--tjs-ink)!important;
}
.tjs-mv4-tier.is-selected::before,.tjs-mv4-tier[data-selected="true"]::before,.tjs-mv4-tier[aria-pressed="true"]::before{transform:scaleX(1)!important}
.tjs-mv5-tier-index{
  display:block;
  font:800 11px/1 var(--tjs-micro);letter-spacing:.04em;
  margin:0 0 28px;
  opacity:.55;
}
.tjs-mv4-tier__kicker{
  font:700 9px/1 var(--tjs-micro);
  letter-spacing:.06em;
  text-transform:uppercase;
  padding:0!important;
  opacity:.8;
}
.tjs-mv4-tier__price{
  font-family:var(--tjs-display);
  font-size:38px;line-height:.9;
  font-weight:700;letter-spacing:-.055em;
  margin:10px 0 9px;
}
.tjs-mv4-tier__value{
  font:800 11px/1 var(--tjs-micro);
  letter-spacing:.02em;text-transform:uppercase;
}
.tjs-mv4-tier__save{font:500 10px/1.2 var(--tjs-text);margin-top:8px;opacity:.68}
.tjs-mv4-tier__badge{
  top:11px!important;right:11px!important;left:auto!important;
  border-radius:1px;
  padding:7px 9px;
  background:var(--tjs-yellow)!important;
  color:var(--tjs-ink)!important;
  font:800 8px/1 var(--tjs-micro);letter-spacing:.01em;
  transform:rotate(-3deg);
  box-shadow:3px 4px 0 rgba(17,17,17,.12)
}
.tjs-mv4-tier__check{
  top:auto!important;right:11px!important;bottom:11px!important;left:auto!important;
  width:28px;height:28px;border-radius:0;
  background:var(--tjs-yellow);color:var(--tjs-ink);
  font-size:0;
}
.tjs-mv4-tier__check::after{content:"↘";font:900 15px/1 var(--tjs-display)}

.tjs-mv4-summary{
  margin-top:12px;
  border-top:1px solid var(--tjs-line-strong);
  border-bottom:1px solid var(--tjs-line-strong);
}
.tjs-mv4-summary__item{padding:13px 8px;text-align:left}
.tjs-mv4-summary__label{font:700 8px/1 var(--tjs-micro);letter-spacing:.06em;color:var(--tjs-muted)}
.tjs-mv4-summary__value{
  font-family:var(--tjs-display);
  font-size:26px;line-height:.95;font-weight:700;letter-spacing:-.045em;
  margin-top:7px
}
.tjs-mv4-cta{
  border-radius:var(--tjs-radius-button);
  height:58px;
  margin-top:12px;
  font:800 12px/1 var(--tjs-micro);letter-spacing:.02em;
  box-shadow:none;
}
.tjs-mv4-cta__arrow{background:var(--tjs-yellow);width:54px;font-size:18px}
.tjs-mv4-cta:hover{box-shadow:none;transform:translateY(-1px)}

/* Editorial proof strip */
.tjs-mv4-trust{
  margin-top:14px;
  grid-template-columns:repeat(2,1fr)!important;
  border-top:1px solid var(--tjs-line-strong);
  border-bottom:1px solid var(--tjs-line-strong);
  counter-reset:tjsTrust;
}
.tjs-mv4-trust__item{
  position:relative;
  padding:13px 12px 13px 30px!important;
  border-left:0!important;
  counter-increment:tjsTrust;
}
.tjs-mv4-trust__item::before{
  content:"0" counter(tjsTrust);
  position:absolute;left:0;top:14px;
  font:800 9px/1 var(--tjs-micro);color:var(--tjs-muted)
}
.tjs-mv4-trust__item:nth-child(even){border-left:1px solid var(--tjs-line)!important}
.tjs-mv4-trust__item:nth-child(n+3){border-top:1px solid var(--tjs-line)}
.tjs-mv4-trust__title{font:800 9px/1 var(--tjs-micro);letter-spacing:.04em}
.tjs-mv4-trust__copy{font:500 10px/1.35 var(--tjs-text);margin-top:5px;color:var(--tjs-muted)}

/* Guarantees: magazine columns, no "AI feature cards" */
.tjs-mv4-guarantees{padding-top:var(--tjs-guarantees-pt,72px);padding-bottom:var(--tjs-guarantees-pb,66px)}
.tjs-mv4-guarantees__grid{grid-template-columns:.9fr 1.35fr;gap:clamp(38px,7vw,100px)}
.tjs-mv4-guarantees__heading{
  font-family:var(--tjs-display);
  font-size:clamp(54px,5.8vw,84px);
  line-height:.84;letter-spacing:-.06em;font-weight:var(--tjs-display-weight,700);
  text-transform:uppercase;
  margin:12px 0 17px
}
.tjs-mv4-guarantees__items{gap:0 26px}
.tjs-mv4-guarantee{min-height:132px;padding:23px 0 22px;border-top:1px solid var(--tjs-line-strong)}
.tjs-mv4-guarantee h3{font-family:var(--tjs-display);font-size:22px;line-height:.98;letter-spacing:-.035em;font-weight:700;margin:0 0 9px;max-width:85%}
.tjs-mv4-guarantee p{font-size:12px;line-height:1.4;color:var(--tjs-muted);max-width:88%}
.tjs-mv4-guarantee__num{
  font-family:var(--tjs-display);font-size:68px;font-weight:800;letter-spacing:-.06em;
  opacity:.06;right:0;top:15px
}

/* Dark campaign poster */
.tjs-mv4-value{padding:18px 0 24px}
.tjs-mv4-value__panel{
  border-radius:0;
  min-height:600px!important;
  padding:clamp(46px,5vw,76px);
  background:
    linear-gradient(rgba(255,255,255,.04) 1px,transparent 1px),
    linear-gradient(90deg,rgba(255,255,255,.04) 1px,transparent 1px),
    radial-gradient(circle at 75% 30%,rgba(215,255,0,.08),transparent 28%),
    var(--tjs-dark);
  background-size:34px 34px,34px 34px,auto,auto;
}
.tjs-mv4-value__headline{
  font-family:var(--tjs-display);
  font-size:clamp(82px,10vw,150px);
  line-height:.76;letter-spacing:-.065em;font-weight:800;
  max-width:1050px
}
.tjs-mv4-value__tape{
  left:31%;top:48%;
  padding:14px 24px;
  border-radius:1px;
  background:var(--tjs-yellow);
  font:900 clamp(17px,2vw,29px)/1 var(--tjs-micro);
  letter-spacing:-.015em;
  box-shadow:8px 9px 0 rgba(0,0,0,.22)
}
.tjs-mv4-value__data{grid-template-columns:repeat(2,minmax(0,350px));gap:54px;margin-top:18px}
.tjs-mv4-value__datum label{font:700 9px/1 var(--tjs-micro);letter-spacing:.06em}
.tjs-mv4-value__datum strong{
  font-family:var(--tjs-display)!important;
  font-size:clamp(58px,6.2vw,88px)!important;
  font-weight:700!important;letter-spacing:-.06em!important
}
.tjs-mv4-value__footer{font:600 10px/1.3 var(--tjs-text);text-transform:uppercase;letter-spacing:.03em}

/* Shake: designed interactive poster */
.tjs-mv4-shake{text-align:left;padding-top:var(--tjs-shake-pt,66px);padding-bottom:var(--tjs-shake-pb,66px)}
.tjs-mv4-shake .tjs-mv4__content{
  display:grid;
  grid-template-columns:minmax(280px,.78fr) minmax(420px,1.22fr);
  grid-template-rows:auto auto;
  gap:0 50px;
  border-top:1px solid var(--tjs-line-strong);
  border-bottom:1px solid var(--tjs-line-strong);
  padding:34px 0;
}
.tjs-mv4-shake .tjs-mv4__content>div:first-child{grid-column:1;grid-row:1;align-self:start}
.tjs-mv4-shake__heading{
  font-family:var(--tjs-display);font-size:clamp(52px,5.8vw,82px);font-weight:700;
  line-height:.84;letter-spacing:-.055em;text-transform:uppercase;
  margin:12px 0 18px
}
.tjs-mv4-shake__stage{grid-column:2;grid-row:1 / span 2;min-height:390px;margin:0;place-items:center}
.tjs-mv4-shake__response{
  grid-column:1;grid-row:2;
  font-family:var(--tjs-display);font-size:28px;font-weight:700;line-height:.95;letter-spacing:-.04em;
  margin:18px 0 0;
  align-self:end
}
.tjs-mv4-shake__hint{grid-column:1;grid-row:2;align-self:end;margin:0 0 39px;font:700 9px/1 var(--tjs-micro);letter-spacing:.05em;text-transform:uppercase;color:var(--tjs-muted)}
.tjs-mv4-shake__halo{border-color:color-mix(in srgb,var(--tjs-yellow) 55%,transparent);border-radius:0;transform:translate(-50%,-50%) rotate(6deg) scale(.72)}

/* Journey: large numbered editorial sequence */
.tjs-mv4-journey{padding-top:var(--tjs-journey-pt,64px);padding-bottom:var(--tjs-journey-pb,48px)}
.tjs-mv4-journey__heading{
  font-family:var(--tjs-display);font-size:clamp(58px,7vw,104px);font-weight:700;
  line-height:.83;letter-spacing:-.06em;text-transform:uppercase;
  margin:12px 0 32px;max-width:980px
}
.tjs-mv4-journey__track{height:3px;background:rgba(17,17,17,.08);margin:0 0 10px}
.tjs-mv4-journey__track span{background:var(--tjs-yellow)}
.tjs-mv4-journey__grid{gap:0}
.tjs-mv4-step{position:relative;min-height:180px;padding:21px 18px 20px 0;border-top:1px solid var(--tjs-line-strong)}
.tjs-mv4-step+.tjs-mv4-step{padding-left:18px;border-left:1px solid var(--tjs-line)}
.tjs-mv4-step__num{font-family:var(--tjs-display);font-size:48px;font-weight:800;letter-spacing:-.06em;color:var(--tjs-ink);margin:0 0 28px;line-height:.8}
.tjs-mv4-step h3{font-family:var(--tjs-display);font-size:22px;line-height:.95;letter-spacing:-.035em;font-weight:700;text-transform:uppercase;margin:0 0 8px}
.tjs-mv4-step p{font-size:12px;line-height:1.4;max-width:280px}

/* Gift: asymmetric campaign spread */
.tjs-mv4-gift{padding-top:var(--tjs-gift-pt,48px);padding-bottom:var(--tjs-gift-pb,48px)}
.tjs-mv4-gift__grid{
  grid-template-columns:1.18fr .82fr;
  min-height:520px;
  border:1px solid var(--tjs-line-strong);
  position:relative;
  overflow:hidden;
  background:var(--tjs-paper)
}
.tjs-mv4-gift__grid::after{
  content:"GIFT / 001";position:absolute;right:14px;top:13px;
  font:800 9px/1 var(--tjs-micro);letter-spacing:.06em;z-index:4
}
.tjs-mv4-gift__media{
  border-right:1px solid var(--tjs-line);
  background:
    linear-gradient(rgba(17,17,17,var(--tjs-grid-alpha,.07)) 1px,transparent 1px),
    linear-gradient(90deg,rgba(17,17,17,var(--tjs-grid-alpha,.07)) 1px,transparent 1px),
    var(--tjs-paper-2);
  background-size:var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),auto;
}
.tjs-mv4-gift__copy{padding:clamp(36px,4.5vw,66px);justify-content:center}
.tjs-mv4-gift__heading{
  font-family:var(--tjs-display);font-size:clamp(54px,6vw,88px);font-weight:700;
  line-height:.84;letter-spacing:-.06em;text-transform:uppercase;
  margin:12px 0 18px
}
.tjs-mv4-gift__box{border-radius:2px;width:76%;background:#141517;box-shadow:18px 22px 0 rgba(17,17,17,.08)}
.tjs-mv4-gift__tag{background:var(--tjs-yellow);border-radius:0;box-shadow:4px 5px 0 rgba(17,17,17,.12)}

/* FAQ: numbered design index */
.tjs-mv4-faq{padding-top:var(--tjs-faq-pt,48px);padding-bottom:var(--tjs-faq-pb,64px)}
.tjs-mv4-faq__heading{
  font-family:var(--tjs-display);font-size:clamp(54px,6.8vw,96px);font-weight:700;
  line-height:.84;letter-spacing:-.06em;text-transform:uppercase;
  margin:12px 0 26px;max-width:1020px
}
.tjs-mv4-faq .tjs-mv4__content>div:last-child{counter-reset:tjsFaq}
.tjs-mv4-faq details{counter-increment:tjsFaq;border-top:1px solid var(--tjs-line-strong)}
.tjs-mv4-faq summary{
  padding:18px 3px;
  display:grid;grid-template-columns:58px 1fr 30px;align-items:center;
  font-family:var(--tjs-display);font-size:18px;line-height:1;font-weight:700;letter-spacing:-.025em;
  text-transform:uppercase
}
.tjs-mv4-faq summary::before{content:"0" counter(tjsFaq);font:800 10px/1 var(--tjs-micro);letter-spacing:.04em;color:var(--tjs-muted)}
.tjs-mv4-faq__plus{font-family:var(--tjs-display);font-size:20px;text-align:right}
.tjs-mv4-faq details[open]{background:color-mix(in srgb,var(--tjs-yellow) 8%,transparent)}
.tjs-mv4-faq details::before{background:var(--tjs-yellow);width:4px}
.tjs-mv4-faq__answer{padding:0 40px 20px 61px;font-size:13px;line-height:1.48;max-width:900px}

/* Final CTA */
.tjs-mv4-final{padding:56px 0 86px}
.tjs-mv4-final .tjs-mv4__content{border-top:1px solid var(--tjs-line-strong);padding-top:34px}
.tjs-mv4-final__heading{
  font-family:var(--tjs-display);font-size:clamp(72px,9vw,138px);font-weight:800;
  line-height:.78;letter-spacing:-.065em;text-transform:uppercase
}
.tjs-mv4-final__meta{font-family:var(--tjs-display);font-weight:700;letter-spacing:-.04em}

/* Sticky CTA */
@media(max-width:749px){
  .tjs-mv4-sticky{background:var(--tjs-ink);border-top:3px solid var(--tjs-yellow);box-shadow:none}
  .tjs-mv4-sticky__price{font-family:var(--tjs-display);font-weight:700;letter-spacing:-.04em}
  .tjs-mv4-sticky__button{border-radius:1px;background:var(--tjs-yellow);font-family:var(--tjs-micro)}
