/* =========================================================
   V5.1 — BOLD TYPE SYSTEM
   Ref direction: thick / clean / minimal / poster-like.
   Commerce behavior intentionally untouched.
   ========================================================= */
:root{
  --tjs-body-weight:500;
  --tjs-micro-weight:800;
  --tjs-value-weight:900;
}

/* Stronger global type hierarchy */
.tjs-mv4{
  font-weight:var(--tjs-body-weight,500);
  -webkit-font-smoothing:antialiased;
  text-rendering:geometricPrecision;
}
.tjs-mv4__eyebrow{
  font-weight:var(--tjs-micro-weight,800)!important;
  letter-spacing:.045em!important;
}
.tjs-mv4__display{
  font-weight:var(--tjs-display-weight,900)!important;
  letter-spacing:-.065em!important;
  line-height:.84!important;
}
.tjs-mv4__body{
  font-weight:var(--tjs-body-weight,500)!important;
  color:color-mix(in srgb,var(--tjs-ink) 72%,transparent)!important;
