/* =========================================================
   V5.3 — INTEGRATED POSTER HERO
   Four deliberate headline lines, softer media/commerce seam,
   tighter artwork relationship, reduced outer rounding.
   Commerce logic untouched.
   ========================================================= */

/* One canvas first: the grid belongs to the hero, not just the media half. */
.tjs-mv4-hero__grid{
  border-radius:var(--tjs-hero-radius,3px)!important;
  overflow:hidden;
  background:
    linear-gradient(rgba(17,17,17,var(--tjs-grid-alpha,.055)) 1px,transparent 1px),
    linear-gradient(90deg,rgba(17,17,17,var(--tjs-grid-alpha,.055)) 1px,transparent 1px),
    radial-gradient(circle at 37% 72%,color-mix(in srgb,var(--tjs-yellow) 10%,transparent),transparent 22%),
    var(--tjs-paper)!important;
  background-size:var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),var(--tjs-grid-size,32px) var(--tjs-grid-size,32px),auto,auto!important;
}

/* Kill the hard split. Media is transparent; commerce fades onto the shared canvas. */
.tjs-mv4-hero__media{
  border-right:0!important;
  background:transparent!important;
}
.tjs-mv4-hero__buy{
  position:relative;
  z-index:3;
  background:linear-gradient(90deg,rgba(247,246,241,0) 0,rgba(247,246,241,.84) var(--tjs-hero-blend,36px),rgba(247,246,241,.98) calc(var(--tjs-hero-blend,36px) + 34px),var(--tjs-paper) 35%)!important;
  margin-left:calc(var(--tjs-hero-blend,36px) * -1);
  padding-left:calc(var(--tjs-desktop-buy-pad,38px) + var(--tjs-hero-blend,36px))!important;
}

/* Four lines are authored, not browser-wrapped. */
.tjs-mv4-hero__h1{
  text-wrap:balance;
  max-width:none!important;
}
.tjs-mv4-hero__h1 .tjs-mv5-hline{
  display:block!important;
  width:max-content!important;
  max-width:100%!important;
  white-space:nowrap!important;
  margin:0!important;
}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(2){margin-top:-.01em!important}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(3){margin-top:.015em!important}
.tjs-mv4-hero__h1 .tjs-mv5-hline:nth-child(4){margin-top:-.005em!important}

/* Highlighter behaves like a physical mark rather than a thin underline. */
.tjs-mv4-highlight::before{
  left:-.06em!important;
  right:-.08em!important;
  bottom:.045em!important;
  height:.27em!important;
  border-radius:1px!important;
  transform:scaleX(0) rotate(-1.2deg) skewX(-3deg)!important;
}
.is-visible .tjs-mv4-highlight::before,
.tjs-mv4-highlight.is-visible::before{
  transform:scaleX(1) rotate(-1.2deg) skewX(-3deg)!important;
}

/* Tighter artwork relationship: push the object up into the previously dead field. */
.tjs-mv4-hero__product{
  width:108%!important;
  height:100%!important;
  transform:translateY(var(--tjs-hero-product-y,-9%)) scale(var(--tjs-hero-product-scale,1.06))!important;
  transform-origin:center 44%!important;
}
.tjs-mv4-hero__img{padding:clamp(4px,1vw,14px)!important}
.tjs-mv4-hero__fallback{width:min(98%,760px)!important}
.tjs-mv4-hero__glow{opacity:.28!important;bottom:8%!important;height:13%!important}

/* Give the campaign metadata proper edge breathing room. */
.tjs-mv4-hero__drop{top:14px!important;left:16px!important;font-size:9px!important}
.tjs-mv4-hero__grid::before{left:16px!important;bottom:14px!important;font-size:9px!important}
.tjs-mv4-hero__grid::after{right:17px!important;top:15px!important}
.tjs-mv4-hero__buy::before{right:16px!important;bottom:14px!important}

@media(min-width:1024px){
  .tjs-mv4-hero__grid{
    min-height:var(--tjs-hero-desktop-height,590px)!important;
  }
  .tjs-mv4-hero__media{
    min-height:var(--tjs-hero-desktop-height,590px)!important;
  }
  .tjs-mv4-hero__buy{
