/* =========================================================
   V5.4 — MANUAL DISPLAY COMPOSITION
   Every major display headline is authored line-by-line.
   No browser word-wrap, hyphenation or mid-word splitting.
   ========================================================= */
.tjs-mv5-manual-heading{
  overflow:visible;
  word-break:keep-all!important;
  overflow-wrap:normal!important;
  hyphens:none!important;
}
.tjs-mv5-manual-line{
  display:block!important;
  width:max-content;
  max-width:100%;
  white-space:nowrap!important;
  word-break:keep-all!important;
  overflow-wrap:normal!important;
  hyphens:none!important;
}

/* Hero: exactly four authored lines. */
.tjs-mv4-hero__h1 .tjs-mv5-manual-line{width:max-content!important;max-width:100%!important}

/* Dark value section: three physical poster lines, not BR-driven wrapping. */
.tjs-mv4-value__headline .tjs-mv5-manual-line{position:relative;z-index:2}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line{animation:tjsKineticLine 520ms var(--tjs-ease-premium) forwards}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line:nth-child(2){animation-delay:80ms}
.tjs-mv4-value__headline.is-visible .tjs-mv5-manual-line:nth-child(3){animation-delay:160ms}

/* Journey: three intentional lines. */
.tjs-mv4-journey__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.035em}

/* Gift: four art-directed lines. Prevent EXPECTED. from ever splitting. */
.tjs-mv4-gift__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.045em}

/* Final CTA: supports up to three intentional lines. */
.tjs-mv4-final__heading .tjs-mv5-manual-line{margin-left:auto;margin-right:auto}
.tjs-mv4-final__heading .tjs-mv5-manual-line + .tjs-mv5-manual-line{margin-top:-.045em}

@media(max-width:749px){
  /* Scale the full authored line rather than allowing a line to wrap. */
  .tjs-mv4-gift__heading{font-size:clamp(30px,10.1vw,42px)!important}
  .tjs-mv4-journey__heading{font-size:clamp(31px,10.2vw,42px)!important}
  .tjs-mv4-final__heading{font-size:clamp(48px,18vw,78px)!important}
  .tjs-mv4-value__headline{font-size:clamp(46px,14.5vw,64px)!important}
}

/* =========================================================
   V5.5 — MOBILE SLIDE TO UNLOCK
   iPhone-inspired drag interaction for the primary mobile CTA.
   Desktop CTA and all cart/variant behavior remain intact.
   ========================================================= */
.tjs-mv5-slide-unlock{display:none}

@keyframes tjsSlideSheen{
  0%{background-position:180% 50%}
  100%{background-position:-80% 50%}
}

@media(max-width:749px){
  .tjs-mv4-hero[data-mobile-slide-enabled="true"] .tjs-mv4-form>.tjs-mv4-cta{display:none!important}
  .tjs-mv4-hero[data-mobile-slide-enabled="true"] .tjs-mv5-slide-unlock{display:block}

  .tjs-mv5-slide-unlock{
    --slide-x:0px;
    --slide-p:0;
    --slide-label-opacity:1;
    position:relative;
    width:100%;
    height:var(--tjs-slide-h,60px);
    margin-top:10px;
    border:1px solid var(--tjs-ink);
    border-radius:3px;
    overflow:hidden;
    background:var(--tjs-ink);
    color:#fff;
    user-select:none;
    -webkit-user-select:none;
    touch-action:pan-y;
    isolation:isolate;
    cursor:default;
  }
  .tjs-mv5-slide-unlock__fill{
    position:absolute;
    inset:0;
    z-index:0;
    background:var(--tjs-yellow);
    transform:scaleX(var(--slide-p,0));
    transform-origin:left center;
    opacity:.20;
    transition:transform 80ms linear,opacity 180ms ease;
    pointer-events:none;
  }
  .tjs-mv5-slide-unlock__label{
    position:absolute;
    inset:0;
    z-index:1;
    display:grid;
    place-items:center;
    padding:0 calc(var(--tjs-slide-thumb,50px) + 18px);
    font-family:var(--tjs-micro,var(--tjs-condensed));
    font-size:10px;
    font-weight:900;
    line-height:1;
    letter-spacing:.12em;
    text-transform:uppercase;
    white-space:nowrap;
    opacity:var(--slide-label-opacity,1);
    transition:opacity 80ms linear,color 180ms ease;
    pointer-events:none;
  }
  .tjs-mv5-slide-unlock.has-shimmer:not(.is-dragging):not(.is-complete):not(.is-disabled) .tjs-mv5-slide-unlock__label{
    color:transparent;
    background:linear-gradient(100deg,#fff 0%,#fff 34%,var(--tjs-yellow) 48%,#fff 62%,#fff 100%);
    background-size:220% 100%;
    -webkit-background-clip:text;
    background-clip:text;
    animation:tjsSlideSheen 2.1s linear infinite;
  }
  .tjs-mv5-slide-unlock__thumb{
    position:absolute;
    z-index:3;
    left:4px;
    top:4px;
    width:var(--tjs-slide-thumb,50px);
    height:calc(100% - 8px);
    min-width:42px;
    display:grid;
    place-items:center;
    border-radius:1px;
    background:var(--tjs-yellow);
    color:var(--tjs-ink);
    box-shadow:0 0 0 1px rgba(255,255,255,.10),4px 0 0 rgba(255,255,255,.06);
    transform:translate3d(var(--slide-x,0px),0,0);
    transition:transform 240ms cubic-bezier(.22,.75,.18,1),background 160ms ease,color 160ms ease;
    cursor:grab;
    touch-action:none;
    will-change:transform;
  }
  .tjs-mv5-slide-unlock__thumb span{
    font-family:var(--tjs-display,Arial,sans-serif);
    font-size:21px;
    font-weight:900;
    line-height:1;
    transform:translateX(1px);
  }
  .tjs-mv5-slide-unlock.is-dragging .tjs-mv5-slide-unlock__thumb{
    transition:none;
    cursor:grabbing;
  }
  .tjs-mv5-slide-unlock.is-dragging .tjs-mv5-slide-unlock__fill{transition:none}
  .tjs-mv5-slide-unlock.is-returning .tjs-mv5-slide-unlock__thumb{transition:transform 260ms cubic-bezier(.2,.8,.2,1)}
  .tjs-mv5-slide-unlock.is-returning .tjs-mv5-slide-unlock__fill{transition:transform 260ms cubic-bezier(.2,.8,.2,1)}
  .tjs-mv5-slide-unlock.is-instant .tjs-mv5-slide-unlock__thumb,
  .tjs-mv5-slide-unlock.is-instant .tjs-mv5-slide-unlock__fill{transition:none!important}
  .tjs-mv5-slide-unlock.is-complete{
    border-color:var(--tjs-yellow);
  }
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__fill{opacity:.94}
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__label{color:var(--tjs-ink);opacity:1;font-weight:900}
  .tjs-mv5-slide-unlock.is-complete .tjs-mv5-slide-unlock__thumb{background:#fff;color:var(--tjs-ink)}
  .tjs-mv5-slide-unlock.is-disabled{
    opacity:.42;
    cursor:not-allowed;
  }
  .tjs-mv5-slide-unlock.is-disabled .tjs-mv5-slide-unlock__thumb{cursor:not-allowed;background:#d8d6cf}
  .tjs-mv5-slide-unlock:focus-visible{outline:3px solid var(--tjs-yellow);outline-offset:3px}
}

@media(prefers-reduced-motion:reduce){
  .tjs-mv5-slide-unlock.has-shimmer .tjs-mv5-slide-unlock__label{animation:none!important;color:#fff!important}
  .tjs-mv5-slide-unlock__thumb,.tjs-mv5-slide-unlock__fill{transition:none!important}
}

