}

.tjs-search-discovery__chips {
  display: flex;
  flex-wrap: wrap;
  gap: 7px;
}

.tjs-search-discovery__chips > button,
.tjs-search-recovery button {
  min-height: 34px;
  display: inline-flex;
  align-items: center;
  padding: 0 11px;
  border: 1px solid rgb(var(--color-line-border));
  border-radius: 999px;
  background: rgb(var(--color-background));
  color: rgb(var(--color-foreground));
  cursor: pointer;
  font: inherit;
  font-size: 9px;
  font-weight: 680;
  transition:
    border-color .18s ease,
    background-color .18s ease,
    transform .18s ease;
}

.tjs-search-discovery__chips > button:hover,
.tjs-search-recovery button:hover {
  border-color: rgb(var(--color-foreground) / .45);
  background: rgb(var(--color-foreground) / .035);
  transform: translateY(-1px);
}

/* Removes hover-only dependency from the header search dropdown. */
.hdt-header-col-search.tjs-search-active .hdt-search-suggests-results,
.hdt-header-col-search:focus-within .hdt-search-suggests-results,
.hdt_predictive-search2.tjs-search-active .hdt-search-suggests-results {
  opacity: 1 !important;
  visibility: visible !important;
}

/* Product-first predictive hierarchy. */
.hdt-cart-show-has-results .hdt-search-products {
  order: 1;
}

.hdt-cart-show-has-results .hdt-search-queries {
  order: 0;
}

.hdt-cart-show-has-results .hdt-search-collections {
  order: 2;
}

.hdt-cart-show-has-results .hdt-search-articles,
.hdt-cart-show-has-results .hdt-search-pages {
  display: none !important;
}

.hdt-mini-search__content {
  scrollbar-gutter: stable;
}

.hdt-search-results-list a:focus-visible,
.tjs-search-keyboard-active {
  outline: 2px solid rgb(var(--color-foreground) / .72) !important;
  outline-offset: 3px;
  border-radius: 4px;
}

.hdt-search-hidden .hdt-search-bottom,
predictive-search[results="true"] .hdt-search-hidden .hdt-search-bottom,
hdt-predictive-search[results="true"] .hdt-search-hidden .hdt-search-bottom {
  display: flex !important;
  opacity: 1 !important;
  visibility: visible !important;
}

.hdt-search-bottom .hdt-view_all {
  min-height: 42px;
  width: 100%;
  justify-content: center !important;
  border-radius: 6px;
  background: rgb(var(--color-foreground));
  color: rgb(var(--color-background)) !important;
  text-decoration: none;
}

.hdt-search-bottom .hdt-view_all::after {
  display: none !important;
}

/* Search-results context and removable smart filters. */
.tjs-search-result-intents {
  display: flex;
  align-items: flex-end;
  justify-content: space-between;
  gap: 16px;
  margin-bottom: 18px;
  padding: 0 0 16px;
  border-bottom: 1px solid rgb(var(--color-line-border));
}

.tjs-search-result-intents__copy {
  min-width: 0;
  display: grid;
  gap: 2px;
}

.tjs-search-result-intents__copy small {
  color: rgb(var(--color-foreground) / .52);
  font-size: 8px;
  font-weight: 730;
  letter-spacing: .07em;
  text-transform: uppercase;
}

.tjs-search-result-intents__copy strong {
  overflow: hidden;
  color: rgb(var(--color-foreground));
  font-size: 20px;
  font-weight: 620;
  letter-spacing: -.025em;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.tjs-search-result-intents__chips {
  min-width: 0;
  display: flex;
  justify-content: flex-end;
  gap: 7px;
  overflow-x: auto;
  scrollbar-width: none;
}

.tjs-search-result-intents__chips::-webkit-scrollbar {
  display: none;
}

.tjs-search-result-intents__chips button {
  min-height: 31px;
  flex: 0 0 auto;
  display: inline-flex;
  align-items: center;
  gap: 6px;
  padding: 0 8px 0 10px;
  border: 1px solid rgb(var(--color-line-border));
  border-radius: 999px;
  background: rgb(var(--color-foreground) / .035);
  color: rgb(var(--color-foreground));
  cursor: pointer;
  font: inherit;
  font-size: 8px;
  font-weight: 720;
  white-space: nowrap;
}

.tjs-search-result-intents__chips button span {
  width: 17px;
  height: 17px;
  display: grid;
  place-items: center;
  border-radius: 50%;
  background: rgb(var(--color-background));
  color: rgb(var(--color-foreground) / .55);
  font-size: 11px;
}

/* Search no-results recovery. */
.tjs-search-recovery {
  width: min(100%, 720px);
  display: grid;
  justify-items: center;
  gap: 9px;
  margin: 12px auto 46px;
  padding: 26px 20px;
  border: 1px solid rgb(var(--color-line-border));
  border-radius: 10px;
  background: rgb(var(--color-foreground) / .025);
  text-align: center;
}

.tjs-search-recovery > small {
  color: rgb(var(--color-foreground) / .52);
  font-size: 8px;
  font-weight: 760;
  letter-spacing: .08em;
  text-transform: uppercase;
}

.tjs-search-recovery h2 {
  margin: 0;
  color: rgb(var(--color-foreground));
  font-size: 24px;
  font-weight: 620;
  letter-spacing: -.03em;
}

.tjs-search-recovery p {
  max-width: 480px;
  margin: 0;
  color: rgb(var(--color-foreground) / .62);
  font-size: 11px;
  line-height: 1.5;
}

.tjs-search-recovery > div {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 7px;
  margin-top: 5px;
}

/* Full search grid consistency. */
.template-search .hdt-main-search .hdt-collection-products {
  grid-template-columns: repeat(4, minmax(0, 1fr)) !important;
}

/* Drawer refinement. */
.hdt-drawer-search::part(overlay) {
  background: rgb(18 14 11 / .48) !important;
  backdrop-filter: blur(2px);
}

.hdt-drawer-search::part(content) {
  box-shadow: -24px 0 70px rgba(20, 15, 12, .16);
}

.hdt-drawer-search .hdt-search-sticky {
  background: rgb(var(--color-background));
}

.hdt-drawer-search .hdt-search-content-title,
.hdt-drawer-search .hdt-search-top-title {
  letter-spacing: -.015em;
}

@media (max-width: 989px) {
  .template-search .hdt-main-search .hdt-collection-products {
    grid-template-columns: repeat(3, minmax(0, 1fr)) !important;
  }
}

@media (max-width: 749px) {
  #drawer-search-form.hdt-drawer-search::part(content),
  .hdt-drawer.hdt-drawer-search::part(content),
  .hdt-drawer-search.hdt-search-hidden::part(content),
  .hdt-drawer-search.hdt-search-fullwidth::part(content) {
    width: 100vw !important;
    max-width: 100vw !important;
    height: 100dvh !important;
    max-height: 100dvh !important;
    padding-top: 0 !important;
    border-radius: 0 !important;
  }

  .hdt-drawer-search::part(close-button) {
    top: 10px !important;
    right: 10px !important;
  }

  .hdt-drawer-search .hdt-search-head {
    min-height: 48px;
    margin: 0 !important;
    padding: 0 48px 0 14px !important;
    border-bottom: 1px solid rgb(var(--color-line-border));
    background: rgb(var(--color-background));
  }

  .hdt-drawer-search .hdt-search-head h5 {
    line-height: 48px !important;
  }

  .hdt-drawer-search .hdt-search-sticky {
    position: sticky;
    z-index: 8;
    top: 0;
    margin: 0 0 14px !important;
    padding: 12px 10px 13px !important;
    border-bottom: 1px solid rgb(var(--color-line-border));
    background: rgb(var(--color-background) / .97);
    backdrop-filter: blur(10px);
  }

  .hdt-drawer-search .hdt-search-content,
  .hdt-search-hidden .hdt-search-content {
    padding-inline: 10px !important;
  }

  .tjs-smart-search-input {
    min-height: 50px !important;
    padding-inline-start: 42px !important;
  }

  .tjs-search-live-intents {
    margin-top: 8px;
  }

  .tjs-search-live-intents > span {
    display: none;
  }

  .tjs-search-discovery {
    margin-bottom: 18px;
    padding: 13px;
  }

  .tjs-search-result-intents {
    align-items: flex-start;
    flex-direction: column;
    gap: 10px;
    margin-bottom: 14px;
    padding-bottom: 13px;
  }

  .tjs-search-result-intents__copy strong {
    max-width: calc(100vw - 28px);
    font-size: 17px;
  }

  .tjs-search-result-intents__chips {
    width: 100%;
    justify-content: flex-start;
  }

  .template-search .hdt-main-search .hdt-collection-products {
    grid-template-columns: repeat(2, minmax(0, 1fr)) !important;
    gap: 10px !important;
  }

  .template-search .hdt-main-search .hdt-container,
  .template-search .hdt-main-search .hdt-container-full {
    padding-inline: 9px !important;
  }

  .hdt-search-hidden .hdt-cart-show-has-results .hdt-row-products {
    gap: 0 !important;
  }

  .hdt-search-hidden .hdt-cart-show-has-results .hdt-pr-loop,
  .hdt-search-hidden .hdt-cart-show-has-results .hdt-card-product {
    padding-bottom: 12px !important;
    margin-bottom: 12px !important;
  }

  .tjs-search-recovery {
    margin-bottom: 30px;
    padding: 22px 14px;
  }

  .tjs-search-recovery h2 {
    font-size: 21px;
  }
}

@media (prefers-reduced-motion: reduce) {
  .tjs-smart-search-input,
  .tjs-search-discovery__chips > button,
  .tjs-search-recovery button,
  .hdt-search-suggests-results {
    transition-duration: .01ms !important;
  }
}
